class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def swap_nodes(head_arr, k):
    head = arr_to_list(head_arr)

    first = head
    for _ in range(k - 1):
        first = first.next
    kth_from_start = first

    second = head
    while first.next:
        first = first.next
        second = second.next
    kth_from_end = second

    kth_from_start.val, kth_from_end.val = kth_from_end.val, kth_from_start.val

    return list_to_arr(head)

